// Parses a form input value (which may be a comma-formatted numeric string, e.g. "1,000")
// into a number, returning null for empty/blank or unparseable values. Used by project
// configuration forms to normalize MoneyInput / numeric fields before submit.
export function toNumberOrNull(value: unknown): number | null {
  if (value === undefined || value === null || value === '') return null;
  const parsed = Number(String(value).replaceAll(',', ''));
  return Number.isFinite(parsed) ? parsed : null;
}
